    # line breaks). skipinitialspace keeps unquoted fields matching the old
    # behaviour; lines that are blank (or quote-balanced empty) are skipped,
    # including blank lines embedded in a quoted field.
    reader = csv.reader(text.splitlines())
    records = [row for row in reader if any(c.strip() for c in row)]
    if not records:
        return []
    header = [h.strip().lower() for h in records[0]]
    missing = [c for c in REQUIRED if c not in header]
    if missing:
